function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 255); // Sky blue
  brush.beginShape();
  brush.vertex(0, 0);       // Top left
  brush.vertex(400, 0);     // Top right
  brush.vertex(200, 400);   // Bottom center
  brush.endShape(true);

  // Hills
  brush.fill("#006400", 255); // Green hills
  brush.beginShape();
  brush.vertex(0, 300);       // Hill top left
  brush.vertex(400, 300);     // Hill top right
  brush.vertex(200, 400);     // Hill bottom center
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 255); // Yellow sun
  brush.beginShape();
  brush.vertex(150, 250);      // Sun top
  brush.vertex(250, 150);      // Sun bottom left
  brush.vertex(350, 150);      // Sun bottom right
  brush.endShape(true);
}
```

